def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n >= 98:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    my_def = 0
    opp_def = 0
    for a in me:
        if a == 'D':
            my_def += 1
    for a in op:
        if a == 'D':
            opp_def += 1

    unprovoked = 0
    for i in range(n):
        if op[i] == 'D':
            if i >= 2:
                if me[i-1] == 'C' and me[i-2] == 'C':
                    unprovoked += 1
            else:
                if all(me[j] == 'C' for j in range(i)):
                    unprovoked += 1

    if unprovoked >= 2:
        return 'D'

    they_retaliated = False
    they_forgave = False
    for i in range(n-1):
        if me[i] == 'D':
            if op[i+1] == 'D':
                they_retaliated = True
            else:
                they_forgave = True

    last_me = me[-1]
    last_op = op[-1]

    def retaliate_or_apologize():
        if last_op == 'D':
            if n >= 2 and (last_me == 'D' or me[-2] == 'D'):
                return 'C'
            elif n == 1 and last_me == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'C'

    if they_retaliated:
        return retaliate_or_apologize()

    if they_forgave:
        if last_op == 'D':
            return retaliate_or_apologize()
        else:
            recent_my_def = 0
            for i in range(max(0, n-3), n):
                if me[i] == 'D':
                    recent_my_def += 1
            if recent_my_def == 0 and n % 7 == 0:
                return 'D'
            return 'C'

    if my_def == 0 and opp_def == 0:
        if n == 4:
            return 'D'
        return 'C'

    return retaliate_or_apologize()
